from .models import InvestigationQualityAssessment

class QualityScoringEngine:
    def assess(self, investigation_id, tenant_id, result):
        data=result.to_dict() if hasattr(result,"to_dict") else (result or {}); evidence=data.get("evidence", data.get("artifacts", [])); iocs=data.get("iocs", data.get("indicators", [])); reasoning=data.get("reasoning_report", data.get("reasoning")); mitre=data.get("mitre", []); timeline=data.get("timeline", []); scores={"evidence":100 if evidence else 0, "enrichment":100 if iocs and data.get("threat_intelligence_report") else 50 if iocs else 0, "reasoning":100 if reasoning and data.get("confidence", data.get("ai_confidence")) is not None else 50 if reasoning else 0, "mitre_mapping":100 if mitre else 0, "timeline":100 if len(timeline)>1 else 50 if timeline else 0, "confidence":min(100,float(data.get("confidence", data.get("ai_confidence",0)))*100) if data.get("confidence", data.get("ai_confidence")) is not None else 0, "completeness":100 if all(data.get(key) for key in ("evidence", "timeline", "mitre")) else 50 if any(data.get(key) for key in ("evidence", "timeline", "mitre")) else 0}; values=list(scores.values()); return InvestigationQualityAssessment(investigation_id, tenant_id, round(sum(values)/len(values),2), scores["evidence"], scores["enrichment"], scores["reasoning"], scores["mitre_mapping"], scores["timeline"], scores["confidence"], scores["completeness"])
